I will scan the active sheet for text cells that match a single letter followed by a number. I will accumulate the numeric part under that letter. Then I will write the totals for the letters in A11:A17 into B11:B17.

```python
import shutil
import re
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else "Sheet1"
vws = vals[sheet_name]
ws = wb[sheet_name]

pattern = re.compile(r"^\s*([A-Za-z])\s*(\d+(?:\.\d+)?)\s*$")
sums = {}

for row in vws.iter_rows():
    for cell in row:
        value = cell.value
        if isinstance(value, str):
            match = pattern.match(value)
            if match:
                letter = match.group(1).upper()
                number = float(match.group(2))
                sums[letter] = sums.get(letter, 0.0) + number

for offset, row in enumerate(range(11, 18)):
    label = ws.cell(row=row, column=1).value
    letter = None

    if isinstance(label, str):
        parts = label.strip().split()
        if parts:
            candidate = parts[-1].upper()
            if len(candidate) == 1 and candidate.isalpha():
                letter = candidate
            else:
                for part in parts:
                    if len(part) == 1 and part.isalpha():
                        letter = part.upper()
                        break

    if letter is None:
        letter = chr(ord("A") + offset)

    total = sums.get(letter, 0.0)
    if total == int(total):
        total = int(total)

    ws.cell(row=row, column=2).value = total
    print(row, letter, total)

wb.save(OUT)
